`timescale 1ns/1ps

module osd_font_rom (
    input  wire        clk,          // 视频时钟（同步读）
    input  wire [7:0]  char_code,
    input  wire [3:0]  row,
    output reg  [15:0] rom_row       // 同步输出：地址后 1 拍有效
);

    localparam [7:0]  CODE_BASE = 8'h20;

    reg [15:0] mem [0:2415];

    wire [7:0]    code_off = char_code - CODE_BASE;
    wire [11:0] addr = ({12{1'b0}} | code_off) << 4 | {12{1'b0}} | row;

    always @(posedge clk)
        rom_row <= mem[addr];

    integer i;
    initial begin
        for (i = 0; i < 2416; i = i + 1) mem[i] = 16'h0000;

